import{_ as a,o as s,c as t,ag as n}from"./chunks/framework.Dk8PTAaz.js";const u=JSON.parse('{"title":"导航流程原理","description":"","frontmatter":{},"headers":[],"relativePath":"guide/navigation-flow.md","filePath":"guide/navigation-flow.md","lastUpdated":1788616892000}'),o={name:"guide/navigation-flow.md"};function i(l,e,c,r,d,p){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="导航流程原理" tabindex="-1">导航流程原理 <a class="header-anchor" href="#导航流程原理" aria-label="Permalink to &quot;导航流程原理&quot;">​</a></h1><p>理解 unix-router 的一次导航从触发到完成发生了什么。</p><h2 id="流程图" tabindex="-1">流程图 <a class="header-anchor" href="#流程图" aria-label="Permalink to &quot;流程图&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes one-dark-pro github-light vp-code" tabindex="0"><code><span class="line"><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">flowchart TD</span></span>
<span class="line"><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">	A[router.push / replace / relaunch] --&gt; B{前一次导航?.}</span></span>
<span class="line"><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">	B -- 是 --&gt; WAIT[等待完成]</span></span>
<span class="line"><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">	WAIT --&gt; C</span></span>
<span class="line"><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">	B -- 否 --&gt; C[matcher.resolve 解析目标]</span></span>
<span class="line"><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">	C --&gt; D{重复导航? push 相同地址}</span></span>
<span class="line"><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">	D -- 是 --&gt; DUP[抛 NAVIGATION_DUPLICATED]</span></span>
<span class="line"><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">	D -- 否 --&gt; E[runBeforeEach 全局前置守卫]</span></span>
<span class="line"><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">	E --&gt; F{结果?}</span></span>
<span class="line"><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">	F -- 中止/取消 --&gt; ABORT[触发 onError + afterEach(fail)]</span></span>
<span class="line"><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">	F -- 重定向 --&gt; REDIRECT{深度超限?}</span></span>
<span class="line"><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">	REDIRECT -- 是 --&gt; CANCEL[取消导航]</span></span>
<span class="line"><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">	REDIRECT -- 否 --&gt; C</span></span>
<span class="line"><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">	F -- 放行 --&gt; G[runBeforeEnter 路由独享守卫]</span></span>
<span class="line"><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">	G --&gt; H[runBeforeResolve 全局解析守卫]</span></span>
<span class="line"><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">	H --&gt; I[调用 uni.* 导航 API]</span></span>
<span class="line"><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">	I --&gt; J{成功?}</span></span>
<span class="line"><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">	J -- 失败 --&gt; APIERR[回退 + 触发保护]</span></span>
<span class="line"><span style="--shiki-dark:#ABB2BF;--shiki-light:#24292E;">	J -- 成功 --&gt; K[更新 currentRoute + runAfterEach]</span></span></code></pre></div><h2 id="执行顺序-前向导航-push-replace-relaunch" tabindex="-1">执行顺序（前向导航 push / replace / relaunch） <a class="header-anchor" href="#执行顺序-前向导航-push-replace-relaunch" aria-label="Permalink to &quot;执行顺序（前向导航 push / replace / relaunch）&quot;">​</a></h2><ol><li><strong>并发排队</strong>：等待上一条导航完成。</li><li><strong>解析目标</strong>：<code>matcher.resolve(location)</code>，产出 <code>RouteLocation</code>。</li><li><strong>重复检测</strong>：<code>push</code> 到与当前相同地址 → <code>NAVIGATION_DUPLICATED</code>。</li><li><strong>全局前置</strong> <code>beforeEach</code></li><li><strong>路由独享</strong> <code>beforeEnter</code>（若配置）</li><li><strong>全局解析</strong> <code>beforeResolve</code></li><li><strong>原生导航</strong>：按 <code>meta.isTab</code> 分发 <code>navigateTo/redirectTo/reLaunch/switchTab</code></li><li><strong>成功后置</strong> <code>afterEach</code>，并更新 <code>currentRoute</code></li></ol><p>任一守卫返回 <code>false</code>/<code>Error</code>/重定向都会中止或改道。重定向深度超过 <code>MAX_REDIRECT_DEPTH</code> 时取消导航。</p><h2 id="返回流程-back" tabindex="-1">返回流程 back <a class="header-anchor" href="#返回流程-back" aria-label="Permalink to &quot;返回流程 back&quot;">​</a></h2><p><code>router.back(delta)</code> 会更短：</p><ol><li>等待前一次导航完成</li><li>从页面栈计算目标页</li><li><code>beforeEach</code> → <code>beforeResolve</code></li><li><code>uni.navigateBack(delta)</code></li><li>同步 <code>currentRoute</code> 并触发 <code>afterEach</code></li></ol><h2 id="状态同步-syncroute" tabindex="-1">状态同步 syncRoute <a class="header-anchor" href="#状态同步-syncroute" aria-label="Permalink to &quot;状态同步 syncRoute&quot;">​</a></h2><p>uni-app x 的物理返回键、tab 切换等<strong>不经过路由器</strong>。<code>install</code> 时注入全局 mixin 在页面 <code>onShow</code> 自动调用 <code>router.syncRoute()</code>，从页面栈重建 <code>currentRoute</code>， 确保 <code>useRoute()</code> 始终反映真实页面。</p><h2 id="冷启动-guardroute" tabindex="-1">冷启动 guardRoute <a class="header-anchor" href="#冷启动-guardroute" aria-label="Permalink to &quot;冷启动 guardRoute&quot;">​</a></h2><p>用户直接进入页面（H5 URL / 场景值 / deeplink）时页面已加载，守卫未执行。 <code>guardRoute()</code> 对当前路由补跑守卫链：放行即返回；重定向则跳转； 中止则触发 <code>onAbort</code>，可转跳安全页。</p><h2 id="你的代码分别在哪一步执行" tabindex="-1">你的代码分别在哪一步执行 <a class="header-anchor" href="#你的代码分别在哪一步执行" aria-label="Permalink to &quot;你的代码分别在哪一步执行&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你的代码</th><th>在哪一步</th></tr></thead><tbody><tr><td><code>matcher.resolve</code> 的解析逻辑</td><td>决定 <code>to</code>（你的 <code>routes</code> 配置）</td></tr><tr><td><code>beforeEach</code></td><td>全局前置（排队后、解析后、重复检测后）</td></tr><tr><td><code>beforeEnter</code></td><td>路由独享前置（beforeEach 之后）</td></tr><tr><td><code>beforeResolve</code></td><td>真正导航前的最后一道闸</td></tr><tr><td><code>uni.*</code> 原生导航</td><td>内部调度（根据 <code>meta.isTab</code> 分发）</td></tr><tr><td><code>afterEach</code> / <code>onRouteChange</code></td><td>导航记账完成后</td></tr><tr><td><code>syncRoute</code></td><td>页面 <code>onShow</code>，从页面栈重建 <code>currentRoute</code></td></tr></tbody></table><h2 id="调度代码速览-对应内部实现" tabindex="-1">调度代码速览（对应内部实现） <a class="header-anchor" href="#调度代码速览-对应内部实现" aria-label="Permalink to &quot;调度代码速览（对应内部实现）&quot;">​</a></h2><p>一次 <code>push</code> 大致经历（伪代码级）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes one-dark-pro github-light vp-code" tabindex="0"><code><span class="line"><span>push(location)</span></span>
<span class="line"><span>  → 若存在 pendingNavigation，等待其完成（并发排队）</span></span>
<span class="line"><span>  → matcher.resolve(location)             // 产出 to</span></span>
<span class="line"><span>  → push 到相同地址?  → 抛 DUPLICATED</span></span>
<span class="line"><span>  → runBeforeEach(to, from)               // 全局前置</span></span>
<span class="line"><span>  → runBeforeEnter(config, to, from)      // 路由独享</span></span>
<span class="line"><span>  → runBeforeResolve(to, from)            // 全局解析</span></span>
<span class="line"><span>  → navigateTo / switchTab / ...          // 真正导航</span></span>
<span class="line"><span>  → 更新 currentRoute + runAfter(to, from) // 记账 + 后置</span></span></code></pre></div><p>要点：</p><ul><li>进入真正的 <code>uni.*</code> 导航前，<code>to</code> 已经过全部守卫确认。</li><li>任一守卫返回非&quot;放行&quot;都会提前返回（<code>abort</code> / <code>redirect</code>），不会触达原生导航。</li><li><code>afterEach</code> 在<code>currentRoute</code> 更新后触发，<code>onRouteChange</code> 监听也在此收到通知。</li></ul>`,21)])])}const g=a(o,[["render",i]]);export{u as __pageData,g as default};
